CAT = "plteoZnaki"; SEG = "ZN"
# Znaki pionowe i poziome, sygnały świetlne. Źródło: rozporządzenie w sprawie znaków i sygnałów
# drogowych (t.j. Dz.U. 2019 poz. 2310), PoRD art. 5. Każdy element: (pytanie, klucz, [3 błędne], wyjaśnienie).
Q = [
("Trójkąt z żółtym tłem i czerwonym obramowaniem, ustawiony wierzchołkiem w dół (znak A-7), oznacza:",
 "Skrzyżowanie z drogą z pierwszeństwem", ["Bezwzględny obowiązek zatrzymania", "Koniec drogi z pierwszeństwem", "Skrzyżowanie dróg równorzędnych"],
 "Znak A-7 „ustąp pierwszeństwa” ostrzega o skrzyżowaniu z drogą z pierwszeństwem (§ 5 ust. 5 rozporządzenia o znakach). Obowiązek zatrzymania się bez względu na ruch wynika dopiero ze znaku B-20."),
("Przed znakiem B-20 „stop” droga z pierwszeństwem jest pusta na całej długości. Co musisz zrobić?",
 "Zatrzymać się mimo pustej drogi", ["Zwolnić i jechać bez zatrzymania", "Zatrzymać się tylko w nocy", "Użyć sygnału dźwiękowego"],
 "Znak B-20 oznacza zakaz wjazdu na skrzyżowanie bez zatrzymania się przed drogą z pierwszeństwem (§ 21 ust. 1 rozporządzenia o znakach). Brak innych pojazdów nie zwalnia z zatrzymania."),
("Znak A-7 stoi wewnątrz dużego skrzyżowania, przed drugą jezdnią drogi dwujezdniowej. Którą jezdnię obejmuje?",
 "Tylko najbliższą jezdnię", ["Obie jezdnie tej drogi", "Całe skrzyżowanie i wyjazd", "Jezdnię, z której wyjeżdżasz"],
 "Znak A-7 umieszczony w obrębie skrzyżowania dotyczy tylko najbliższej jezdni, przed którą stoi (§ 5 ust. 5 rozporządzenia o znakach)."),
("Żółty romb w białym obramowaniu (znak D-1) informuje, że:",
 "Jedziesz drogą z pierwszeństwem", ["Zbliżasz się do ronda", "Wjeżdżasz do strefy zamieszkania", "Kończy się droga ekspresowa"],
 "Znak D-1 „droga z pierwszeństwem” oznacza początek lub kontynuację drogi z pierwszeństwem (§ 43 rozporządzenia o znakach)."),
("Żółty romb przekreślony czarnymi ukośnymi kreskami (znak D-2) oznacza:",
 "Koniec drogi z pierwszeństwem", ["Zakaz wyprzedzania na odcinku", "Początek drogi jednokierunkowej", "Koniec obszaru zabudowanego"],
 "Znak D-2 oznacza koniec drogi z pierwszeństwem (§ 43 ust. 3 rozporządzenia o znakach); dalej obowiązują znaki lub zasada prawej ręki."),
("Pod znakiem D-1 wisi tabliczka T-6a z pogrubioną linią skręcającą w lewo. Co ona pokazuje?",
 "Rzeczywisty przebieg drogi głównej", ["Nakaz skrętu w lewo tuż za znakiem", "Objazd na czas robót drogowych", "Pas ruchu przeznaczony dla autobusów"],
 "Tabliczka T-6a pod znakiem D-1 wskazuje rzeczywisty przebieg drogi z pierwszeństwem przez skrzyżowanie (§ 43 ust. 2 rozporządzenia o znakach)."),
("Okrągła niebieska tarcza z czerwonym obramowaniem i dwoma skrzyżowanymi czerwonymi pasami (znak B-36) oznacza:",
 "Zakaz zatrzymywania się", ["Zakaz postoju powyżej minuty", "Zakaz wjazdu w obu kierunkach", "Koniec wszystkich zakazów"],
 "Znak B-36 „zakaz zatrzymywania się” oznacza zakaz zatrzymania pojazdu (§ 28 ust. 2 rozporządzenia o znakach). Przekreślenie jednym pasem to znak B-35, zakaz postoju."),
("Przy znaku B-35 „zakaz postoju” bez tabliczki chcesz wysadzić pasażera. Na jak długo wolno ci się zatrzymać?",
 "Najwyżej na jedną minutę", ["Najwyżej na pięć minut", "Na dowolnie długi czas", "Na żaden czas, nawet krótki"],
 "Postój to unieruchomienie dłuższe niż 1 minuta (PoRD art. 2 pkt 30). Znak B-35 zakazuje postoju, więc zatrzymanie do minuty jest dozwolone."),
("Znak B-36 stoi po prawej stronie jezdni dwukierunkowej. Gdzie obowiązuje zakaz?",
 "Po stronie, gdzie jest znak", ["Po obu stronach jezdni", "Tylko na poboczu drogi", "Po przeciwnej stronie jezdni"],
 "Zakaz wyrażony znakiem B-35 lub B-36 dotyczy tej strony drogi, po której znak się znajduje (§ 28 ust. 3 pkt 1 rozporządzenia o znakach)."),
("Zakaz ze znaku B-36 nie został odwołany żadnym znakiem. Do jakiego miejsca obowiązuje?",
 "Do najbliższego skrzyżowania", ["Do końca całej miejscowości", "Na odcinku 500 m za znakiem", "Do odwołania przez policjanta"],
 "Jeżeli zakaz z m.in. znaków B-25, B-33, B-35 i B-36 nie zostanie odwołany wcześniej, obowiązuje do najbliższego skrzyżowania (§ 32 ust. 2 rozporządzenia o znakach)."),
("Obowiązuje znak B-25 „zakaz wyprzedzania”. Czy możesz wyprzedzić jadący przed tobą motocykl jednośladowy?",
 "Tak, zakaz dotyczy wielośladów", ["Nie, zakaz obejmuje wszystkich", "Tak, ale tylko poza miastem", "Nie, chyba że motocykl zwolni"],
 "Znak B-25 zabrania kierującym pojazdami silnikowymi wyprzedzania pojazdów silnikowych wielośladowych (§ 23 ust. 1 rozporządzenia o znakach). Motocykl jednośladowy do nich nie należy."),
("Czym różni się znak B-2 „zakaz wjazdu” od znaku B-1 „zakaz ruchu w obu kierunkach”?",
 "B-2 zakazuje wjazdu od strony znaku", ["B-2 dotyczy tylko ciężarówek", "B-2 obowiązuje tylko w nocy", "B-2 dopuszcza ruch pojazdów silnikowych"],
 "Znak B-2 zakazuje wjazdu na drogę od strony jego umieszczenia, a B-1 zakazuje ruchu po drodze w ogóle (§ 16 i § 17 rozporządzenia o znakach)."),
("Pod znakiem D-3 „droga jednokierunkowa” jest tabliczka „Nie dotyczy” z symbolem roweru. Co to oznacza?",
 "Rowery mogą jechać pod prąd", ["Rowerzystom zakazano wjazdu", "Droga jest tylko dla rowerów", "Rowery muszą jechać chodnikiem"],
 "Tabliczka „Nie dotyczy” pod znakiem D-3 wskazuje, że ruch pojazdów pokazanych na tabliczce odbywa się w dwóch kierunkach (§ 44 ust. 2 rozporządzenia o znakach)."),
("Przed rondem stoją razem znaki C-12 „ruch okrężny” i A-7. Kto ma pierwszeństwo?",
 "Kierujący jadący już po rondzie", ["Kierujący wjeżdżający na rondo", "Pojazd nadjeżdżający z prawej", "Pojazd o większej masie całkowitej"],
 "Znak C-12 występujący łącznie ze znakiem A-7 oznacza pierwszeństwo kierującego znajdującego się na skrzyżowaniu przed wjeżdżającym (§ 36 ust. 2 rozporządzenia o znakach)."),
("Trójkątny znak ostrzegawczy z sylwetkami dwojga biegnących dzieci (A-17) ostrzega przed:",
 "Miejscem uczęszczanym przez dzieci", ["Przejściem dla pieszych z sygnalizacją", "Placem zabaw zamkniętym dla aut", "Strefą zamieszkania za znakiem"],
 "Znak A-17 „dzieci” ostrzega o miejscu szczególnie uczęszczanym przez dzieci lub o bliskości takiego miejsca (§ 8 ust. 2 rozporządzenia o znakach)."),
("Znak ostrzegawczy z symbolem parowozu (A-10) informuje, że przejazd kolejowy jest:",
 "Bez zapór i półzapór", ["Wyposażony w zapory", "Wyłączony z użytkowania", "Obsługiwany przez dróżnika"],
 "Znak A-10 ostrzega o przejeździe kolejowym bez zapór i półzapór, a znak A-9 z symbolem płotu o przejeździe z zaporami lub półzaporami (§ 6 rozporządzenia o znakach)."),
("Mijasz słupek wskaźnikowy z dwiema czerwonymi kreskami (G-1b). Co to oznacza?",
 "Zbliżasz się do przejazdu kolejowego", ["Za słupkiem jest zjazd z autostrady", "Do granicy miasta zostały dwa kilometry", "Za słupkiem kończy się pobocze"],
 "Słupki wskaźnikowe G-1 informują o zbliżaniu się do przejazdu kolejowego; słupek z dwiema kreskami stoi zwykle na 2/3 odległości znaku ostrzegawczego od przejazdu (§ 78 rozporządzenia o znakach)."),
("Na jezdni wymalowano dwie równoległe linie ciągłe między kierunkami ruchu (P-4). Co oznaczają?",
 "Zakaz przejeżdżania i najeżdżania", ["Pas o zmiennym kierunku ruchu", "Miejsce do zawracania", "Linię dla pojazdów uprzywilejowanych"],
 "Znak P-4 „linia podwójna ciągła” rozdziela pasy o kierunkach przeciwnych i oznacza zakaz przejeżdżania przez tę linię i najeżdżania na nią (§ 86 rozporządzenia o znakach)."),
("Linia przerywana, w której kreski są dłuższe od przerw (P-6), uprzedza o:",
 "Zbliżaniu się do linii ciągłej", ["Końcu zakazu wyprzedzania", "Pasie ruchu dla rowerów", "Możliwości postoju przy krawędzi"],
 "Znak P-6 „linia ostrzegawcza” uprzedza o zbliżaniu się do linii, przez którą przejeżdżanie jest zabronione, lub do miejsca niebezpiecznego (§ 86 ust. 7 rozporządzenia o znakach)."),
("Poprzeczna linia z białych trójkątów (P-13) wskazuje miejsce zatrzymania w związku ze znakiem:",
 "A-7 „ustąp pierwszeństwa”", ["B-20 „stop”", "D-6 „przejście dla pieszych”", "B-36 „zakaz zatrzymywania się”"],
 "Znak P-13 „linia warunkowego zatrzymania złożona z trójkątów” wskazuje miejsce zatrzymania w celu ustąpienia pierwszeństwa ze znaku A-7 (§ 89 ust. 2 rozporządzenia o znakach). Ze znakiem B-20 występuje linia ciągła P-12."),
("Szeroka ciągła linia poprzeczna z napisem STOP (P-12) wskazuje miejsce zatrzymania przy znaku:",
 "B-20 „stop”", ["A-7 „ustąp pierwszeństwa”", "C-12 „ruch okrężny”", "A-9 „przejazd z zaporami”"],
 "Znak P-12 „linia bezwzględnego zatrzymania, stop” wskazuje miejsce zatrzymania w związku ze znakami B-20 lub B-32 (§ 89 ust. 1 rozporządzenia o znakach)."),
("Linia złożona z prostokątów (P-14) wyznacza miejsce zatrzymania między innymi:",
 "Przed przejściem dla pieszych", ["Na środku ronda przy wysepce", "Przed znakiem D-1 na drodze głównej", "Na pasie awaryjnym autostrady"],
 "Znak P-14 wskazuje miejsce zatrzymania m.in. na wlotach dróg równorzędnych, przed przejściem dla pieszych, przed przejazdem kolejowym i przed sygnałem świetlnym (§ 89 ust. 3 rozporządzenia o znakach)."),
("Zapala się sygnał żółty, a ty jesteś tak blisko sygnalizatora, że zatrzymanie wymagałoby gwałtownego hamowania. Co robisz?",
 "Możesz jechać dalej", ["Hamujesz awaryjnie przed linią", "Cofasz za linię zatrzymania", "Zatrzymujesz się na skrzyżowaniu"],
 "Sygnał żółty oznacza zakaz wjazdu, chyba że pojazd jest tak blisko, że nie może się zatrzymać bez gwałtownego hamowania (§ 95 ust. 1 pkt 2 rozporządzenia o znakach)."),
("Na sygnalizatorze palą się jednocześnie światło czerwone i żółte. Co to oznacza?",
 "Zakaz wjazdu, zaraz zapali się zielone", ["Możesz ruszać, zielone już się pali", "Sygnalizator jest uszkodzony, jedź ostrożnie", "Zakaz wjazdu, zaraz zgaśnie wszystko"],
 "Sygnały czerwony i żółty nadawane jednocześnie oznaczają zakaz wjazdu i to, że za chwilę zapali się sygnał zielony (§ 95 ust. 1 pkt 4 rozporządzenia o znakach)."),
("Pali się czerwone światło, a obok niego zielona strzałka w prawo (sygnalizator S-2). Jak możesz skręcić?",
 "Najpierw się zatrzymując", ["Bez zatrzymywania, jak na zielonym", "Tylko gdy czerwone zacznie migać", "Tylko za pojazdem uprzywilejowanym"],
 "Skręcanie przy sygnale zielonej strzałki jest dozwolone pod warunkiem zatrzymania się przed sygnalizatorem i nieutrudniania ruchu innym (§ 96 ust. 3 rozporządzenia o znakach)."),
("Przy czerwonym świetle pali się zielona strzałka w lewo. Czy z lewego skrajnego pasa wolno ci zawrócić?",
 "Tak, jeśli nie ma znaku B-23", ["Nie, strzałka dotyczy skrętu", "Tak, bez zatrzymania", "Tylko nocą przy pustej drodze"],
 "Zielona strzałka zezwalająca na skręt w lewo zezwala też na zawracanie z lewego skrajnego pasa, chyba że zabrania tego znak B-23 (§ 96 ust. 2 rozporządzenia o znakach); najpierw trzeba się zatrzymać."),
("Masz zielone światło, ale za skrzyżowaniem stoi korek i nie zdążysz z niego zjechać. Co robisz?",
 "Czekasz przed skrzyżowaniem", ["Wjeżdżasz, bo zielone zezwala", "Wjeżdżasz i czekasz na środku", "Omijasz korek pasem do skrętu"],
 "Sygnał zielony nie zezwala na wjazd, jeżeli opuszczenie skrzyżowania nie byłoby możliwe przed zakończeniem nadawania tego sygnału (§ 95 ust. 2 rozporządzenia o znakach; PoRD art. 25 ust. 4)."),
("Policjant kieruje ruchem na skrzyżowaniu z działającą sygnalizacją i znakami. Czyje polecenia są najważniejsze?",
 "Policjanta", ["Sygnalizatora", "Znaków pionowych", "Znaków poziomych"],
 "Polecenia i sygnały osób kierujących ruchem mają pierwszeństwo przed sygnałami świetlnymi i znakami drogowymi (PoRD art. 5 ust. 2)."),
("Przed skrzyżowaniem stoi znak A-7, ale działa sygnalizacja i masz zielone. Według czego jedziesz?",
 "Według sygnałów świetlnych", ["Według znaku A-7", "Według zasady prawej ręki", "Według znaku D-1 na poprzecznej"],
 "Sygnały świetlne mają pierwszeństwo przed znakami drogowymi regulującymi pierwszeństwo przejazdu (PoRD art. 5 ust. 3). Znak A-7 zacznie obowiązywać, gdy sygnalizacja zostanie wyłączona."),
("Na sygnalizatorze miga pojedyncze żółte światło. Co ono nakazuje?",
 "Szczególną ostrożność", ["Bezwzględne zatrzymanie", "Zwiększenie prędkości", "Zjazd na prawe pobocze"],
 "Migający sygnał żółty ostrzega o niebezpieczeństwie lub utrudnieniu ruchu i nakazuje zachowanie szczególnej ostrożności (§ 98 ust. 6 rozporządzenia o znakach); pierwszeństwo wynika wtedy ze znaków."),
("Niebieski prostokątny znak z domkiem, dorosłym i dzieckiem grającym w piłkę (D-40) oznacza:",
 "Wjazd do strefy zamieszkania", ["Wjazd na obszar zabudowany", "Parking dla rodzin z dziećmi", "Drogę wewnętrzną osiedla"],
 "Znak D-40 oznacza wjazd do strefy zamieszkania, a D-41 wyjazd z niej (§ 58 rozporządzenia o znakach). W strefie pieszy ma pierwszeństwo przed pojazdem."),
("Biała tablica z czarnymi sylwetkami budynków (D-42) oznacza:",
 "Wjazd na obszar zabudowany", ["Wjazd do strefy zamieszkania", "Początek strefy płatnego parkowania", "Zakaz używania sygnału dźwiękowego"],
 "Znak D-42 „obszar zabudowany” oznacza wjazd na obszar zabudowany, a D-43 wyjazd z niego (§ 58 ust. 3 rozporządzenia o znakach)."),
("Widzisz niebieski kwadratowy znak D-6 z pieszym na pasach. Do czego cię zobowiązuje?",
 "Do zmniejszenia prędkości", ["Do zatrzymania się zawsze", "Do użycia klaksonu", "Do zmiany pasa w lewo"],
 "Kierujący zbliżający się do miejsca oznaczonego znakiem D-6 jest obowiązany zmniejszyć prędkość tak, aby nie narazić pieszych na tym miejscu lub na nie wchodzących (§ 47 ust. 4 rozporządzenia o znakach)."),
("Trójkątny znak z wykrzyknikiem (A-30) ma pod sobą tabliczkę. Po co jest ta tabliczka?",
 "Wskazuje rodzaj niebezpieczeństwa", ["Podaje dopuszczalną prędkość", "Określa godziny obowiązywania", "Odwołuje wcześniejsze zakazy ze znaków"],
 "Znak A-30 „inne niebezpieczeństwo” ostrzega o niebezpieczeństwie innym niż na pozostałych znakach, a tabliczka pod nim wskazuje jego rodzaj (§ 11 rozporządzenia o znakach)."),
("Na drodze o dopuszczalnej prędkości 90 km/h mijasz znak ostrzegawczy bez tabliczki T-1. W jakiej odległości jest zwykle niebezpieczne miejsce?",
 "Od 150 do 300 m", ["Od 20 do 50 m", "Od 500 do 1000 m", "Od 1 do 2 km"],
 "Na drogach, gdzie dopuszczalna prędkość przekracza 60 km/h, znak ostrzegawczy stoi od 150 do 300 m przed miejscem niebezpiecznym, na pozostałych do 100 m (§ 3 ust. 2 rozporządzenia o znakach)."),
("Okrągły znak z białym tłem i czerwonym obramowaniem, z czarną zawróconą strzałką przekreśloną czerwonym pasem (B-23), zabrania:",
 "Zawracania", ["Skrętu w lewo", "Cofania", "Wjazdu na rondo"],
 "Znak B-23 „zakaz zawracania” zabrania zawracania do najbliższego skrzyżowania włącznie (§ 22 ust. 5 rozporządzenia o znakach); zakaz skrętu w lewo to znak B-21."),
("Biała tablica z czarnymi sylwetkami budynków przekreślona czerwonym ukośnym pasem (D-43) oznacza:",
 "Koniec obszaru zabudowanego", ["Koniec strefy zamieszkania", "Koniec drogi z pierwszeństwem", "Koniec drogi ekspresowej"],
 "Znak D-43 oznacza wyjazd z obszaru zabudowanego (§ 58 ust. 3 rozporządzenia o znakach); od tego miejsca obowiązują ogólne limity prędkości poza obszarem zabudowanym."),
("Trójkątny znak z wypukłością na jezdni (A-11a) ostrzega przed:",
 "Progiem zwalniającym", ["Koleinami na jezdni", "Spadającymi kamieniami", "Mostem zwodzonym"],
 "Znak A-11a „próg zwalniający” ostrzega o wypukłości na jezdni zastosowanej w celu spowolnienia ruchu (§ 7 ust. 2 rozporządzenia o znakach). Poprzeczną nierówność jezdni oznacza znak A-11."),
]
